 fn run(input:String)->String{let r=(||->Result<serde_json::Value,String>{let v:serde_json::Value=serde_json::from_str(&input).map_err(|e|e.to_string())?;let raw=v["headers"].as_str().ok_or("missing headers")?;let mut h:BTreeMap<String,Vec<String>>=BTreeMap::new();let mut status=None;for line in raw.lines(){let line=line.trim_end_matches('\r');if line.starts_with("HTTP/"){status=Some(line.to_string());continue}if let Some((k,val))=line.split_once(':'){h.entry(k.trim().to_ascii_lowercase()).or_default().push(val.trim().to_string());}}let checks=[("strict-transport-security","Enforces HTTPS in supporting clients"),("content-security-policy","Restricts permitted content sources"),("x-content-type-options","Reduces MIME sniffing"),("x-frame-options","Legacy framing control"),("referrer-policy","Controls referrer information"),("permissions-policy","Restricts browser features")];let observations=checks.iter().map(|(name,desc)|serde_json::json!({"header":name,"present":h.contains_key(*name),"description":desc})).collect::<Vec<_>>();let cookies=h.get("set-cookie").cloned().unwrap_or_default().iter().map(|c|{let low=c.to_ascii_lowercase();serde_json::json!({"value":c,"secure":low.split(';').any(|x|x.trim()=="secure"),"http_only":low.split(';').any(|x|x.trim()=="httponly"),"same_site":low.split(';').any(|x|x.trim().starts_with("samesite=") )})}).collect::<Vec<_>>();Ok(serde_json::json!({"status_line":status,"headers":h,"security_headers":observations,"cookies":cookies,"note":"Header presence is contextual; this report is not a vulnerability verdict."}))})();match r{Ok(x)=>x.to_string(),Err(e)=>serde_json::json!({"error":e}).to_string()}}
